<div class="d-flex flex-wrap gap-2 mb-3 align-items-center"><span class="badge text-bg-<?= $st === 'paid' ? 'success' : ($st === 'approved' ? 'info' : 'secondary') ?> fs-6"><?= ['draft' => 'مسودة', 'approved' => 'معتمد', 'paid' => 'مصروف'][$st] ?></span><strong><?= e($run['period']) ?></strong>
 <span class="ms-auto d-flex flex-wrap gap-2"><a class="btn btn-outline-secondary btn-sm" href="<?= url("school/payroll/$id/export.xlsx") ?>"><i class="bi bi-file-earmark-excel"></i> Excel</a>
 <?php if ($draft): ?><button class="btn btn-success btn-sm" data-api="<?= url("api/v1/school/payroll/$id/approve") ?>" data-confirm="اعتماد الكشف؟ لن يمكن تعديله بعد ذلك إلا بإعادة فتحه.">اعتماد</button><button class="btn btn-outline-danger btn-sm" data-api="<?= url("api/v1/school/payroll/$id") ?>" data-method="DELETE" data-confirm="حذف المسودة؟">حذف</button><?php endif; ?>
 <?php if ($st === 'approved'): ?><button class="btn btn-primary btn-sm" data-api="<?= url("api/v1/school/payroll/$id/paid") ?>" data-body='{"paid_on":"<?= date('Y-m-d') ?>"}' data-confirm="تأكيد صرف الرواتب اليوم؟">تم الصرف</button><button class="btn btn-outline-secondary btn-sm" data-api="<?= url("api/v1/school/payroll/$id/reopen") ?>" data-prompt="سبب إعادة الفتح" data-prompt-field="reason">إعادة فتح</button><?php endif; ?></span></div>
<div class="card-s mb-3"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>الموظف</th><th>أيام</th><th>الأساسي</th><th>بدلات</th><th>خصومات</th><th>الصافي</th><th></th></tr></thead><tbody>
<?php foreach ($run['items'] as $i): ?><tr><td><?= e($i['full_name']) ?> <small class="text-muted"><?= e($i['job_title'] ?? '') ?></small></td><td><?= (int)$i['days_worked'] ?>/<?= (int)$i['days_in_month'] ?></td><td dir="ltr"><?= e(number_format((float)$i['base'], 2)) ?> <?= e($i['currency']) ?></td>
<?php if ($draft): ?><td colspan="2"><form class="d-flex gap-1" method="post" action="<?= url('api/v1/school/payroll/items/' . (int)$i['id']) ?>" data-ajax data-reload novalidate><?= csrf_field() ?><input class="form-control form-control-sm" style="width:6rem" name="allowances" value="<?= e($i['allowances']) ?>" dir="ltr" aria-label="بدلات"><input class="form-control form-control-sm" style="width:6rem" name="deductions" value="<?= e($i['deductions']) ?>" dir="ltr" aria-label="خصومات"><button class="btn btn-sm btn-outline-primary">حفظ</button></form></td>
<?php else: ?><td dir="ltr"><?= e(number_format((float)$i['allowances'], 2)) ?></td><td dir="ltr"><?= e(number_format((float)$i['deductions'], 2)) ?></td><?php endif; ?>
<td dir="ltr"><strong><?= e(number_format((float)$i['net'], 2)) ?></strong></td><td><a class="btn btn-sm btn-outline-secondary" target="_blank" href="<?= url('school/payroll/slip/' . (int)$i['id']) ?>">قسيمة</a></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card-s"><h2 class="h6">الإجمالي لكل عملة (دون تحويل بين العملات)</h2><?php foreach ($run['totals'] as $cur => $t): ?><div dir="ltr" class="text-end"><strong><?= e($cur) ?></strong>: أساسي <?= e(number_format((float)$t['base'], 2)) ?> + بدلات <?= e(number_format((float)$t['allowances'], 2)) ?> − خصومات <?= e(number_format((float)$t['deductions'], 2)) ?> = <strong><?= e(number_format((float)$t['net'], 2)) ?></strong></div><?php endforeach; ?></div>
